import UIKit
import QuartzCore

// MARK: - MirrorOverlayRecord

final class MirrorOverlayRecord {
    let elementID: String
    let elementType: String
    let view: UIView
    var lastFrame: CGRect = .zero
    var lastRadius: CGFloat = 0
    var lastOpacity: CGFloat = 1
    var lastZIndex: CGFloat = 0

    init(elementID: String, elementType: String, view: UIView) {
        self.elementID = elementID
        self.elementType = elementType
        self.view = view
    }
}

// MARK: - MirrorOverlayManagerDelegate

protocol MirrorOverlayManagerDelegate: AnyObject {
    func overlayManager(_ manager: MirrorOverlayManager, didAddOverlay record: MirrorOverlayRecord)
    func overlayManager(_ manager: MirrorOverlayManager, didRemoveOverlay record: MirrorOverlayRecord)
}

// MARK: - MirrorOverlayManager

/// Maintains a registry of native UIView overlays that mirror DOM element geometry
/// reported by the JavaScript LayoutBridge. All mutations happen on the main thread
/// (driven by CADisplayLink). Avoids redundant UIView updates via frame/opacity caches.
final class MirrorOverlayManager {

    // MARK: - Properties

    weak var delegate: MirrorOverlayManagerDelegate?

    private(set) weak var containerView: UIView?

    /// Active overlays keyed by element ID as reported by JS.
    private var registry: [String: MirrorOverlayRecord] = [:]

    /// Controls whether overlays are rendered. Set false to hide all mirrors.
    var isEnabled: Bool = true {
        didSet {
            containerView?.isHidden = !isEnabled
        }
    }

    // MARK: - Init

    init(containerView: UIView) {
        self.containerView = containerView
    }

    // MARK: - Apply Layout

    /// Called every CADisplayLink tick with the latest decoded layout payload.
    /// Must be called on the main thread.
    func apply(elements: [LayoutElement]) {
        guard isEnabled, let container = containerView else { return }

        var seenIDs = Set<String>()
        seenIDs.reserveCapacity(elements.count)

        for element in elements {
            guard element.width > 0, element.height > 0 else { continue }
            seenIDs.insert(element.id)

            let nativeFrame = element.frame

            if let record = registry[element.id] {
                updateRecord(record, element: element, newFrame: nativeFrame)
            } else {
                let view = buildView(for: element, frame: nativeFrame)
                view.alpha = element.resolvedOpacity
                view.layer.zPosition = element.resolvedZIndex

                container.addSubview(view)

                let record = MirrorOverlayRecord(
                    elementID: element.id,
                    elementType: element.type,
                    view: view
                )
                record.lastFrame = nativeFrame
                record.lastOpacity = element.resolvedOpacity
                record.lastZIndex = element.resolvedZIndex
                record.lastRadius = element.resolvedBorderRadius
                registry[element.id] = record

                delegate?.overlayManager(self, didAddOverlay: record)
            }
        }

        // Remove stale overlays
        let staleIDs = Set(registry.keys).subtracting(seenIDs)
        for staleID in staleIDs {
            guard let record = registry.removeValue(forKey: staleID) else { continue }
            record.view.removeFromSuperview()
            delegate?.overlayManager(self, didRemoveOverlay: record)
        }
    }

    // MARK: - Private Update

    private func updateRecord(_ record: MirrorOverlayRecord, element: LayoutElement, newFrame: CGRect) {
        // Frame — skip if unchanged
        if record.lastFrame != newFrame {
            UIView.performWithoutAnimation {
                record.view.frame = newFrame
            }
            record.lastFrame = newFrame
            // Resize gradient sublayers if present
            resizeGradientLayers(in: record.view, to: newFrame.size)
        }

        // Opacity
        let opacity = element.resolvedOpacity
        if abs(record.lastOpacity - opacity) > 0.005 {
            record.view.alpha = opacity
            record.lastOpacity = opacity
        }

        // Z position
        let z = element.resolvedZIndex
        if abs(record.lastZIndex - z) > 0.5 {
            record.view.layer.zPosition = z
            record.lastZIndex = z
        }

        // Corner radius
        let radius = element.resolvedBorderRadius
        if abs(record.lastRadius - radius) > 0.5 {
            applyCornerRadius(radius, to: record.view)
            record.lastRadius = radius
        }
    }

    private func resizeGradientLayers(in view: UIView, to size: CGSize) {
        for sublayer in view.layer.sublayers ?? [] {
            if let grad = sublayer as? CAGradientLayer {
                CATransaction.begin()
                CATransaction.setDisableActions(true)
                grad.frame = CGRect(origin: .zero, size: size)
                CATransaction.commit()
            }
        }
    }

    private func applyCornerRadius(_ radius: CGFloat, to view: UIView) {
        if let effect = view as? UIVisualEffectView {
            effect.layer.cornerRadius = radius
            effect.clipsToBounds = radius > 0
        } else {
            view.layer.cornerRadius = radius
            view.clipsToBounds = radius > 0
        }
    }

    // MARK: - View Factory

    private func buildView(for element: LayoutElement, frame: CGRect) -> UIView {
        switch element.type {

        case "lg":
            return buildLiquidGlassView(element: element, frame: frame)

        case "bubble":
            return buildBubbleView(element: element, frame: frame)

        case "ib-wrap":
            return buildInputBarView(element: element, frame: frame)

        case "ta":
            return buildTextAreaView(element: element, frame: frame)

        case "hcard":
            return buildHCardView(element: element, frame: frame)

        default:
            return buildGenericView(element: element, frame: frame)
        }
    }

    // MARK: - Specific View Builders

    private func buildLiquidGlassView(element: LayoutElement, frame: CGRect) -> UIView {
        let style: UIBlurEffect.Style
        if #available(iOS 13.0, *) {
            style = .systemUltraThinMaterialDark
        } else {
            style = .dark
        }
        let effect = UIBlurEffect(style: style)
        let effectView = UIVisualEffectView(effect: effect)
        effectView.frame = frame
        effectView.layer.cornerRadius = element.resolvedBorderRadius
        if #available(iOS 13.0, *) {
            effectView.layer.cornerCurve = .continuous
        }
        effectView.clipsToBounds = true
        effectView.layer.borderWidth = 0.5
        effectView.layer.borderColor = UIColor(white: 1.0, alpha: 0.13).cgColor
        effectView.isUserInteractionEnabled = false

        // Specular highlight at top edge
        let highlight = CALayer()
        highlight.frame = CGRect(x: 0, y: 0, width: frame.width, height: 1)
        highlight.backgroundColor = UIColor(white: 1.0, alpha: 0.10).cgColor
        effectView.layer.addSublayer(highlight)

        // Shadow
        effectView.layer.masksToBounds = false
        effectView.layer.shadowColor = UIColor.black.cgColor
        effectView.layer.shadowOffset = CGSize(width: 0, height: 12)
        effectView.layer.shadowRadius = 20
        effectView.layer.shadowOpacity = 0.28

        return effectView
    }

    private func buildBubbleView(element: LayoutElement, frame: CGRect) -> UIView {
        let view = UIView(frame: frame)
        view.layer.cornerRadius = element.resolvedBorderRadius
        if #available(iOS 13.0, *) {
            view.layer.cornerCurve = .continuous
        }
        view.clipsToBounds = true
        view.isUserInteractionEnabled = false

        // Base tint
        view.backgroundColor = UIColor(red: 0, green: 9.0/255, blue: 205.0/255, alpha: 0.72)

        // Gradient overlay
        let grad = CAGradientLayer()
        grad.frame = CGRect(origin: .zero, size: frame.size)
        grad.colors = [
            UIColor(red: 0,          green: 9.0/255,   blue: 205.0/255, alpha: 0.82).cgColor,
            UIColor(red: 70.0/255,   green: 80.0/255,  blue: 230.0/255, alpha: 0.75).cgColor,
            UIColor(red: 95.0/255,   green: 106.0/255, blue: 247.0/255, alpha: 0.68).cgColor
        ]
        grad.startPoint = CGPoint(x: 0, y: 0)
        grad.endPoint   = CGPoint(x: 1, y: 1)
        grad.cornerRadius = element.resolvedBorderRadius
        view.layer.insertSublayer(grad, at: 0)

        // Border
        view.layer.borderWidth = 0.5
        view.layer.borderColor = UIColor(red: 150.0/255, green: 160.0/255, blue: 1.0, alpha: 0.3).cgColor

        // Shadow
        view.layer.masksToBounds = false
        view.layer.shadowColor = UIColor(red: 0, green: 0, blue: 0.6, alpha: 0.45).cgColor
        view.layer.shadowOffset = CGSize(width: 0, height: 4)
        view.layer.shadowRadius = 8
        view.layer.shadowOpacity = 1.0

        return view
    }

    private func buildInputBarView(element: LayoutElement, frame: CGRect) -> UIView {
        let view = UIView(frame: frame)
        view.backgroundColor = .clear
        view.layer.cornerRadius = element.resolvedBorderRadius
        view.isUserInteractionEnabled = false
        return view
    }

    private func buildTextAreaView(element: LayoutElement, frame: CGRect) -> UIView {
        let view = UIView(frame: frame)
        view.backgroundColor = UIColor(white: 1.0, alpha: 0.045)
        view.layer.cornerRadius = element.resolvedBorderRadius
        if #available(iOS 13.0, *) {
            view.layer.cornerCurve = .continuous
        }
        view.clipsToBounds = true
        view.isUserInteractionEnabled = false
        view.layer.borderWidth = 0.5
        view.layer.borderColor = UIColor(white: 1.0, alpha: 0.08).cgColor
        return view
    }

    private func buildHCardView(element: LayoutElement, frame: CGRect) -> UIView {
        let style: UIBlurEffect.Style
        if #available(iOS 13.0, *) {
            style = .systemThinMaterialDark
        } else {
            style = .dark
        }
        let effectView = UIVisualEffectView(effect: UIBlurEffect(style: style))
        effectView.frame = frame
        effectView.layer.cornerRadius = element.resolvedBorderRadius
        if #available(iOS 13.0, *) {
            effectView.layer.cornerCurve = .continuous
        }
        effectView.clipsToBounds = true
        effectView.layer.borderWidth = 0.5
        effectView.layer.borderColor = UIColor(white: 1.0, alpha: 0.10).cgColor
        effectView.isUserInteractionEnabled = false
        return effectView
    }

    private func buildGenericView(element: LayoutElement, frame: CGRect) -> UIView {
        let view = UIView(frame: frame)
        view.backgroundColor = element.resolvedColor ?? .clear
        view.layer.cornerRadius = element.resolvedBorderRadius
        if #available(iOS 13.0, *) {
            view.layer.cornerCurve = .continuous
        }
        view.isUserInteractionEnabled = false
        return view
    }

    // MARK: - Trait Changes

    /// Call when the user interface style changes so blur effects update.
    func updateForTraitCollection(_ traitCollection: UITraitCollection) {
        guard #available(iOS 13.0, *) else { return }
        let style: UIBlurEffect.Style = traitCollection.userInterfaceStyle == .dark
            ? .systemUltraThinMaterialDark
            : .systemUltraThinMaterialLight
        for (_, record) in registry {
            if record.elementType == "lg", let effectView = record.view as? UIVisualEffectView {
                effectView.effect = UIBlurEffect(style: style)
            }
        }
    }

    // MARK: - Lifecycle

    /// Removes all overlays and clears the registry.
    func invalidate() {
        for (_, record) in registry {
            record.view.removeFromSuperview()
        }
        registry.removeAll()
    }

    /// Returns the overlay record for the given element ID, if it exists.
    func record(forID elementID: String) -> MirrorOverlayRecord? {
        registry[elementID]
    }
}

