import UIKit
import QuartzCore

final class MirrorOverlayRecord {
    let elementID: String
    let elementType: String
    let view: UIView
    var lastFrame: CGRect = .zero
    var lastRadius: CGFloat = 0
    var lastOpacity: CGFloat = 1
    var lastZIndex: CGFloat = 0

    init(elementID: String, elementType: String, view: UIView) {
        self.elementID = elementID
        self.elementType = elementType
        self.view = view
    }
}

protocol MirrorOverlayManagerDelegate: AnyObject {
    func overlayManager(_ manager: MirrorOverlayManager, didAddOverlay record: MirrorOverlayRecord)
    func overlayManager(_ manager: MirrorOverlayManager, didRemoveOverlay record: MirrorOverlayRecord)
}

final class MirrorOverlayManager {
    weak var delegate: MirrorOverlayManagerDelegate?

    private(set) weak var containerView: UIView?

    private var registry: [String: MirrorOverlayRecord] = [:]

    var isEnabled: Bool = true {
        didSet {
            containerView?.isHidden = !isEnabled
        }
    }

    init(containerView: UIView) {
        self.containerView = containerView
    }

    func apply(elements: [LayoutElement]) {
        precondition(Thread.isMainThread)

        guard isEnabled, let container = containerView else {
            return
        }

        var seenIDs = Set<String>()
        seenIDs.reserveCapacity(elements.count)

        for element in elements {
            guard element.width > 0, element.height > 0 else {
                continue
            }

            seenIDs.insert(element.id)

            let nativeFrame = element.frame

            if let record = registry[element.id] {
                updateRecord(record, element: element, newFrame: nativeFrame)
            } else {
                let view = buildView(for: element, frame: nativeFrame)
                view.alpha = element.resolvedOpacity
                view.layer.zPosition = element.resolvedZIndex

                container.addSubview(view)

                let record = MirrorOverlayRecord(
                    elementID: element.id,
                    elementType: element.type,
                    view: view
                )

                record.lastFrame = nativeFrame
                record.lastOpacity = element.resolvedOpacity
                record.lastZIndex = element.resolvedZIndex
                record.lastRadius = element.resolvedBorderRadius

                registry[element.id] = record
                delegate?.overlayManager(self, didAddOverlay: record)
            }
        }

        let staleIDs = Set(registry.keys).subtracting(seenIDs)

        for staleID in staleIDs {
            guard let record = registry.removeValue(forKey: staleID) else {
                continue
            }

            record.view.removeFromSuperview()
            delegate?.overlayManager(self, didRemoveOverlay: record)
        }
    }

    private func updateRecord(
        _ record: MirrorOverlayRecord,
        element: LayoutElement,
        newFrame: CGRect
    ) {
        if record.lastFrame != newFrame {
            UIView.performWithoutAnimation {
                record.view.frame = newFrame
            }

            record.lastFrame = newFrame
            updateOverlayLayout(for: record.view)
        }

        let opacity = element.resolvedOpacity

        if abs(record.lastOpacity - opacity) > 0.005 {
            record.view.alpha = opacity
            record.lastOpacity = opacity
        }

        let zIndex = element.resolvedZIndex

        if abs(record.lastZIndex - zIndex) > 0.5 {
            record.view.layer.zPosition = zIndex
            record.lastZIndex = zIndex
        }

        let radius = element.resolvedBorderRadius

        if abs(record.lastRadius - radius) > 0.5 {
            applyCornerRadius(radius, to: record.view)
            record.lastRadius = radius
            updateOverlayLayout(for: record.view)
        }
    }

    private func applyCornerRadius(_ radius: CGFloat, to view: UIView) {
        view.layer.cornerRadius = radius

        if #available(iOS 13.0, *) {
            view.layer.cornerCurve = .continuous
        }
    }

    private func configureShadow(
        for view: UIView,
        color: UIColor,
        offset: CGSize,
        radius: CGFloat,
        opacity: Float
    ) {
        view.layer.masksToBounds = false
        view.layer.shadowColor = color.cgColor
        view.layer.shadowOffset = offset
        view.layer.shadowRadius = radius
        view.layer.shadowOpacity = opacity
    }

    private func updateOverlayLayout(for view: UIView) {
        let bounds = view.bounds
        let cornerRadius = view.layer.cornerRadius

        CATransaction.begin()
        CATransaction.setDisableActions(true)

        for subview in view.subviews {
            if subview.tag == 1 {
                subview.frame = bounds
                subview.layer.cornerRadius = cornerRadius

                if #available(iOS 13.0, *) {
                    subview.layer.cornerCurve = .continuous
                }

                subview.clipsToBounds = true

                for layer in subview.layer.sublayers ?? [] {
                    layer.frame = subview.bounds

                    if let gradientLayer = layer as? CAGradientLayer {
                        gradientLayer.cornerRadius = cornerRadius
                    }
                }

                if let effectView = subview as? UIVisualEffectView {
                    effectView.contentView.frame = effectView.bounds

                    for layer in effectView.contentView.layer.sublayers ?? [] {
                        layer.frame = effectView.contentView.bounds
                    }
                }
            }
        }

        view.layer.shadowPath = UIBezierPath(
            roundedRect: bounds,
            cornerRadius: cornerRadius
        ).cgPath

        CATransaction.commit()
    }

    private func buildView(for element: LayoutElement, frame: CGRect) -> UIView {
        switch element.type {
        case "lg":
            return buildLiquidGlassView(element: element, frame: frame)
        case "bubble":
            return buildBubbleView(element: element, frame: frame)
        case "ib-wrap":
            return buildInputBarView(element: element, frame: frame)
        case "ta":
            return buildTextAreaView(element: element, frame: frame)
        case "hcard":
            return buildHCardView(element: element, frame: frame)
        default:
            return buildGenericView(element: element, frame: frame)
        }
    }

    private func makeContentContainer(
        frame: CGRect,
        cornerRadius: CGFloat
    ) -> UIView {
        let contentView = UIView(frame: frame)
        contentView.tag = 1
        contentView.layer.cornerRadius = cornerRadius

        if #available(iOS 13.0, *) {
            contentView.layer.cornerCurve = .continuous
        }

        contentView.clipsToBounds = true
        contentView.isUserInteractionEnabled = false
        return contentView
    }

    private func buildLiquidGlassView(
        element: LayoutElement,
        frame: CGRect
    ) -> UIView {
        let hostView = UIView(frame: frame)
        hostView.backgroundColor = .clear
        hostView.isUserInteractionEnabled = false
        applyCornerRadius(element.resolvedBorderRadius, to: hostView)

        configureShadow(
            for: hostView,
            color: .black,
            offset: CGSize(width: 0, height: 12),
            radius: 20,
            opacity: 0.28
        )

        let contentContainer = makeContentContainer(
            frame: hostView.bounds,
            cornerRadius: element.resolvedBorderRadius
        )

        let style: UIBlurEffect.Style

        if #available(iOS 13.0, *) {
            style = .systemUltraThinMaterialDark
        } else {
            style = .dark
        }

        let effectView = UIVisualEffectView(effect: UIBlurEffect(style: style))
        effectView.frame = contentContainer.bounds
        effectView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        effectView.isUserInteractionEnabled = false

        let highlight = CALayer()
        highlight.name = "MirrorOverlayManager.highlight"
        highlight.frame = CGRect(
            x: 0,
            y: 0,
            width: effectView.contentView.bounds.width,
            height: 1
        )
        highlight.backgroundColor = UIColor(
            white: 1.0,
            alpha: 0.10
        ).cgColor
        effectView.contentView.layer.addSublayer(highlight)

        contentContainer.addSubview(effectView)
        hostView.addSubview(contentContainer)

        hostView.layer.borderWidth = 0.5
        hostView.layer.borderColor = UIColor(
            white: 1.0,
            alpha: 0.13
        ).cgColor

        updateOverlayLayout(for: hostView)
        return hostView
    }

    private func buildBubbleView(
        element: LayoutElement,
        frame: CGRect
    ) -> UIView {
        let hostView = UIView(frame: frame)
        hostView.backgroundColor = .clear
        hostView.isUserInteractionEnabled = false
        applyCornerRadius(element.resolvedBorderRadius, to: hostView)

        configureShadow(
            for: hostView,
            color: UIColor(
                red: 0,
                green: 0,
                blue: 0.6,
                alpha: 0.45
            ),
            offset: CGSize(width: 0, height: 4),
            radius: 8,
            opacity: 1.0
        )

        let contentContainer = makeContentContainer(
            frame: hostView.bounds,
            cornerRadius: element.resolvedBorderRadius
        )

        contentContainer.backgroundColor = UIColor(
            red: 0,
            green: 9.0 / 255.0,
            blue: 205.0 / 255.0,
            alpha: 0.72
        )

        let gradientLayer = CAGradientLayer()
        gradientLayer.frame = contentContainer.bounds
        gradientLayer.colors = [
            UIColor(
                red: 0,
                green: 9.0 / 255.0,
                blue: 205.0 / 255.0,
                alpha: 0.82
            ).cgColor,
            UIColor(
                red: 70.0 / 255.0,
                green: 80.0 / 255.0,
                blue: 230.0 / 255.0,
                alpha: 0.75
            ).cgColor,
            UIColor(
                red: 95.0 / 255.0,
                green: 106.0 / 255.0,
                blue: 247.0 / 255.0,
                alpha: 0.68
            ).cgColor
        ]
        gradientLayer.startPoint = CGPoint(x: 0, y: 0)
        gradientLayer.endPoint = CGPoint(x: 1, y: 1)
        gradientLayer.cornerRadius = element.resolvedBorderRadius
        contentContainer.layer.insertSublayer(gradientLayer, at: 0)

        contentContainer.layer.borderWidth = 0.5
        contentContainer.layer.borderColor = UIColor(
            red: 150.0 / 255.0,
            green: 160.0 / 255.0,
            blue: 1.0,
            alpha: 0.3
        ).cgColor

        hostView.addSubview(contentContainer)

        updateOverlayLayout(for: hostView)
        return hostView
    }

    private func buildInputBarView(
        element: LayoutElement,
        frame: CGRect
    ) -> UIView {
        let view = UIView(frame: frame)
        view.backgroundColor = .clear
        view.isUserInteractionEnabled = false
        applyCornerRadius(element.resolvedBorderRadius, to: view)

        let contentContainer = makeContentContainer(
            frame: view.bounds,
            cornerRadius: element.resolvedBorderRadius
        )

        view.addSubview(contentContainer)
        updateOverlayLayout(for: view)
        return view
    }

    private func buildTextAreaView(
        element: LayoutElement,
        frame: CGRect
    ) -> UIView {
        let hostView = UIView(frame: frame)
        hostView.backgroundColor = .clear
        hostView.isUserInteractionEnabled = false
        applyCornerRadius(element.resolvedBorderRadius, to: hostView)

        let contentContainer = makeContentContainer(
            frame: hostView.bounds,
            cornerRadius: element.resolvedBorderRadius
        )

        contentContainer.backgroundColor = UIColor(
            white: 1.0,
            alpha: 0.045
        )
        contentContainer.layer.borderWidth = 0.5
        contentContainer.layer.borderColor = UIColor(
            white: 1.0,
            alpha: 0.08
        ).cgColor

        hostView.addSubview(contentContainer)
        updateOverlayLayout(for: hostView)
        return hostView
    }

    private func buildHCardView(
        element: LayoutElement,
        frame: CGRect
    ) -> UIView {
        let hostView = UIView(frame: frame)
        hostView.backgroundColor = .clear
        hostView.isUserInteractionEnabled = false
        applyCornerRadius(element.resolvedBorderRadius, to: hostView)

        let contentContainer = makeContentContainer(
            frame: hostView.bounds,
            cornerRadius: element.resolvedBorderRadius
        )

        let style: UIBlurEffect.Style

        if #available(iOS 13.0, *) {
            style = .systemThinMaterialDark
        } else {
            style = .dark
        }

        let effectView = UIVisualEffectView(effect: UIBlurEffect(style: style))
        effectView.frame = contentContainer.bounds
        effectView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        effectView.isUserInteractionEnabled = false

        contentContainer.addSubview(effectView)
        contentContainer.layer.borderWidth = 0.5
        contentContainer.layer.borderColor = UIColor(
            white: 1.0,
            alpha: 0.10
        ).cgColor

        hostView.addSubview(contentContainer)

        updateOverlayLayout(for: hostView)
        return hostView
    }

    private func buildGenericView(
        element: LayoutElement,
        frame: CGRect
    ) -> UIView {
        let hostView = UIView(frame: frame)
        hostView.backgroundColor = .clear
        hostView.isUserInteractionEnabled = false
        applyCornerRadius(element.resolvedBorderRadius, to: hostView)

        let contentContainer = makeContentContainer(
            frame: hostView.bounds,
            cornerRadius: element.resolvedBorderRadius
        )

        contentContainer.backgroundColor = element.resolvedColor ?? .clear

        hostView.addSubview(contentContainer)
        updateOverlayLayout(for: hostView)
        return hostView
    }

    func updateForTraitCollection(_ traitCollection: UITraitCollection) {
        guard #available(iOS 13.0, *) else {
            return
        }

        let liquidGlassStyle: UIBlurEffect.Style = traitCollection.userInterfaceStyle == .dark
            ? .systemUltraThinMaterialDark
            : .systemUltraThinMaterialLight

        let cardStyle: UIBlurEffect.Style = traitCollection.userInterfaceStyle == .dark
            ? .systemThinMaterialDark
            : .systemThinMaterialLight

        for record in registry.values {
            let effectStyle: UIBlurEffect.Style?

            switch record.elementType {
            case "lg":
                effectStyle = liquidGlassStyle
            case "hcard":
                effectStyle = cardStyle
            default:
                effectStyle = nil
            }

            guard let effectStyle else {
                continue
            }

            updateBlurEffects(
                in: record.view,
                style: effectStyle
            )
        }
    }

    private func updateBlurEffects(
        in view: UIView,
        style: UIBlurEffect.Style
    ) {
        for subview in view.subviews {
            if let effectView = subview as? UIVisualEffectView {
                effectView.effect = UIBlurEffect(style: style)
            }

            updateBlurEffects(in: subview, style: style)
        }
    }

    func invalidate() {
        for record in registry.values {
            record.view.removeFromSuperview()
        }

        registry.removeAll()
    }

    func record(forID elementID: String) -> MirrorOverlayRecord? {
        registry[elementID]
    }
}
